// ora-mod-cst — generated by tools/merge.js: src/ora-mod-cst-*.js plus matching questions from the Oracle role banks (tools/modules.js).
// Oracle Modules — Cost Management. Format: [topic, question, answer, 'B'|'D']
QB['ora-mod-cst'] = (QB['ora-mod-cst'] || []).concat([
['Setup', 'What are the key Cost Management setups in Fusion?',
`- **Cost organizations** and relationships to inventory orgs.
- **Cost books** (primary, secondary) and assignment to cost orgs.
- **Valuation structures** and **valuation units**.
- **Cost profiles**: item cost profiles (cost method, valuation structure, cost determination) and **default cost profiles**.
- **Cost elements** and **cost element groups** (material, overhead, resource).
- **Cost component mappings** and **expense pools**.
- **Accounting** rules (SLA for cost accounting and receipt accounting).`, 'B'],

['Setup', 'What are cost elements and analysis groups?',
`- **Cost elements**: buckets for cost (material, freight, duty, overhead, labor, machine).
- **Cost element groups** organize them for reporting.
- **Analysis groups** give alternative groupings (e.g. by cost type for margin analysis).
- Landed cost charges and overheads map to specific elements.`, 'D'],

['Processes', 'What is the sequence of cost processing in Fusion?',
`- **Transfer Transactions from Inventory/Receiving to Costing**.
- **Cost processor** (Process Costing / cost transactions) values transactions by cost method.
- **Create Cost Accounting Distributions** and **Create Receipt Accounting Distributions**.
- **Create Accounting** (SLA) → transfer to GL.
- Scheduled frequently (hourly/daily) for timely valuation.`, 'D'],

['Standard Cost', 'How do you create and publish standard costs?',
`- **Cost planning**: create a **cost scenario**, enter/import standard costs (material, overhead) and resource rates.
- **Roll up** costs for manufactured items through structures/work definitions.
- **Review** with finance (simulations, variance to current).
- **Publish** the scenario with an effective date → on-hand revalued, revaluation posted.`, 'D'],

['Average Cost', 'How does perpetual average cost handle receipts and returns?',
`- Each receipt recalculates average = (on-hand value + receipt value) / (on-hand qty + receipt qty).
- Issues/shipments at current average.
- Returns to supplier at the **receipt cost** or current average depending on settings — can create variances.
- Negative on-hand causes **cost adjustments** later when receipts arrive.`, 'D'],

['Variances', 'Name the main variances in Fusion Cost Management.',
`- **Purchase price variance (PPV)** (standard costing).
- **Invoice price variance (IPV)** between PO and invoice.
- **Work order variances**: material usage, resource efficiency/rate, overhead, scrap.
- **Cycle count/physical inventory adjustments**.
- **Cost revaluation** on standard cost updates.`, 'B'],

['Landed Cost', 'How are landed costs allocated?',
`- **Charge references** (freight, duty, insurance) with **allocation basis** (quantity, weight, volume, amount).
- Estimated charges via **landed cost charge templates** on POs/trade operations; actuals from AP invoices.
- Charges allocated to receipt lines → increase item cost; variances between estimated and actual adjusted.`, 'D'],

['Accounting', 'What accounting does Cost Management create for a PO receipt into inventory under standard cost?',
`- **Receipt Accounting**: Dr Receiving Inspection, Cr Accrual (at PO price) — for standard routing.
- **Delivery to inventory**: Dr Inventory (standard), Dr/Cr **PPV**, Cr Receiving Inspection.
- **AP invoice**: Dr Accrual, Cr Liability, IPV for differences.
- Shipment: Dr COGS (or Deferred COGS), Cr Inventory at standard.`, 'D'],

['Accounting', 'What is deferred COGS and when is it used?',
`- When revenue is deferred (e.g. customer acceptance), COGS is held in **Deferred COGS** and recognized in proportion to revenue.
- **COGS recognition** process uses revenue recognition events from AR/Revenue Management.
- Ensures margin matching (matching principle).`, 'D'],

['Period Close', 'What is the cost period close checklist?',
`- All inventory/receiving transactions transferred and **costed** (no errors).
- Landed cost and accrual adjustments processed.
- Work orders closed; variances calculated.
- **Create Cost/Receipt Accounting** run and transferred to GL.
- **Inventory valuation** reconciled to GL.
- **Close the cost period**; open next.`, 'B'],

['Reporting', 'Which Cost Management reports do you use?',
`- **Inventory valuation** (perpetual) by cost org/valuation unit/item.
- **Item cost** and cost history reports.
- **Margin analysis** (gross margin by item/customer).
- **Receipt accounting / accrual reconciliation** reports.
- **Cost accounting distributions** and **work order variance** reports.`, 'B'],

['Interview', 'Tell me how you would troubleshoot inventory valuation that doesn\'t match GL.',
`- **Same timing**: valuation as of period end, GL closed?
- **Uncosted/unaccounted** transactions or transfers not run.
- **Manual journals** in GL to inventory accounts.
- **Account mapping** differences (expense subinventories, in-transit).
- **Revaluations** posted in a different period.
- Fix root causes and document a monthly reconciliation.`, 'D']
]);

QB['ora-mod-cst'] = (QB['ora-mod-cst'] || []).concat([["Costing","How would you design the costing architecture for a multi-entity manufacturer?","- **Cost orgs** per plant (standard cost, roll-ups with resources/overhead).\n- **Cost books**: primary (GAAP) and secondary (management/IFRS or group view with intercompany markup eliminated).\n- **Valuation units** at cost org level (or by lot for high-value items).\n- **Transfer pricing** via SFO for intercompany movements.\n- **Landed costs** for imports.\n- **Variance analysis** reporting.\n- **Standard cost cycle**: annual update with simulation, approvals, revaluation.","D"],["Costing","How would you support a company switching from average to standard cost?","- Business case and finance approval (variances, reporting).\n- **Set standard costs** for all items (from recent average/actual costs and roll-ups).\n- **Timing** at a period/year start; **revaluation** of on-hand at switch.\n- **Cost profiles** changed for items/cost orgs; new **variance accounts**.\n- Test thoroughly (receipts, work orders, shipments).\n- Train finance on variance analysis.","D"],["Costing","What costing methods does Oracle support?","Fusion Cost Management supports:\n- **Standard cost** — a fixed cost per item; differences go to variance accounts (e.g. purchase price variance).\n- **Perpetual average cost** — cost updates with each receipt.\n- **Actual cost (FIFO/LIFO)** — cost layers consumed in order.\n\nEBS: Standard, Average, FIFO, LIFO, plus Periodic Average/Incremental LIFO.\n\nCost method is set by **cost organization and cost book** in Fusion (by inventory org in EBS).","B"],["Costing","What is the difference between Receipt Accounting and Cost Accounting in Fusion?","- **Receipt Accounting** creates the accounting for receipts, deliveries and returns, and manages **accruals** (receipt accrual, period-end accrual for expense items). It also handles accrual clearing and write-offs.\n- **Cost Accounting** costs **inventory transactions** (issues, transfers, shipments, production) using the cost method, creating entries like Dr COGS / Cr Inventory.\n- Both run their own **Create Accounting** processes and transfer to GL.\n\nTip: Mention that you schedule Transfer Transactions to Costing and Create Cost Accounting regularly.","D"],["Costing","What is purchase price variance (PPV)?","Under **standard costing**, inventory is valued at standard cost. When you buy at a different price:\n- **PPV = (PO price − standard cost) × quantity received.**\n- Example: standard $10, PO price $11, 100 units → $100 unfavorable PPV.\n- Accounting at receipt/delivery: Dr Inventory $1,000 (standard), Dr PPV $100, Cr Accrual $1,100.\n- Invoice price variance (IPV) captures differences between invoice and PO price.\n\nPPV is watched closely by procurement and finance to measure buying performance.","B"],["Costing","How does a standard cost update work?","- Create a **new cost scenario** with new standard costs (often yearly or quarterly).\n- **Roll up** costs for manufactured items (material + resources + overhead).\n- Review and **publish** the scenario.\n- On publish, Oracle revalues on-hand inventory at the new cost and posts the difference to a **standard cost adjustment / revaluation** account.\n\nTip: Mention you run a \"what-if\" report first so finance sees the revaluation impact before publishing.","D"],["Costing","Why might an item's cost show as zero in Fusion and what do you check?","- No **standard cost** defined (standard costing) or no receipts yet (average costing).\n- **Item cost profile** missing or wrong.\n- Cost processor hasn't run, or transactions are **uncosted** due to errors.\n- Wrong cost org/book or valuation unit.\nFix the setup, run the cost processor, and review the item's cost history.","D"],["Costing","How do you reconcile inventory valuation to the General Ledger?","- Run the **inventory valuation report** (perpetual) as of period end by cost org/valuation unit.\n- Compare to **GL inventory account balances** (by org via cost center or org segment).\n- Differences: un-costed transactions, cost accounting not created/transferred, manual GL journals to inventory accounts, wrong account mapping in cost accounting rules.\n- Use **third-party/control-account style** discipline: block manual journals to inventory accounts.\n- Close the **cost period** only after reconciling.","D"],["Costing","What are the steps of the cost period close in Fusion Cost Management?","- Make sure inventory/receiving/WIP transactions are complete and **transferred to costing**.\n- Run the **cost processor**; fix errors.\n- Run **Create Receipt Accounting** and **Create Cost Accounting**; transfer to GL.\n- Process **landed cost** adjustments and **standard cost updates** if any.\n- **Close** work orders and calculate variances.\n- Review **unprocessed transactions**; reconcile valuation to GL.\n- **Close the cost period** (cost org/book), then open the next.","D"],["Costing","How do you handle intercompany profit in inventory with SFO?","- When one entity sells to another at transfer price above cost, the buying entity's inventory includes **intercompany profit**.\n- SFO with **transfer pricing** creates the intercompany sale/purchase and costs in each entity.\n- At group level, **unrealized profit in inventory** must be **eliminated** in consolidation until the goods are sold externally.\n- Fusion can track **profit in inventory** (e.g. via cost books/elemental costs for intercompany markup) to support elimination.\n- Agree the approach with group finance.","D"],["Costing","How do you explain a large purchase price variance to the business?","- Break PPV down by **item, supplier, category** and period.\n- Causes: price increases, spot buys off-contract, outdated standards, currency movements, freight in price.\n- Actions: update standards, negotiate agreements, enforce catalog buying.\n- Present with trend charts and the top 10 drivers.","D"],["Costing","What are cost organizations, cost books and valuation units in Fusion Cost Management?","- **Cost organization** — a group of inventory orgs that share costing (e.g. a plant and its satellite warehouses).\n- **Cost book** — a set of costing policies; primary book for financial reporting, plus optional others (e.g. for management or local GAAP).\n- **Valuation structure / valuation unit** — the level at which costs are kept (e.g. by cost org, by cost org + subinventory, or by lot).\n- **Cost profiles** assign the cost method (standard, average, FIFO) to items via **item cost profiles** and defaults.\n\nThese replace EBS's per-org cost method.","D"],["Costing","How do you troubleshoot an inventory transaction that hasn't been costed?","- Check **Transfer Transactions from Inventory to Costing** ran and succeeded.\n- Look at **Review Cost Accounting Processes** / **Cost Processor errors**: missing cost, missing item cost profile, missing valuation unit, period closed in costing.\n- Check the **cost accounting distributions** for errors in Create Cost Accounting (SLA account errors).\n- Fix the root cause (e.g. define the missing standard cost), then re-run the cost processor.\n- Make sure the cost period is open.","D"],["Costing","How do landed costs work in Fusion?","**Landed Cost Management** adds freight, duties, insurance and other charges to the item cost:\n- Define **charge references** and **allocation basis** (quantity, weight, value, volume).\n- Estimate charges on the PO (via **landed cost charge templates**) and/or use actuals from **trade operations** and AP invoices.\n- Charges are allocated to receipt lines and included in inventory valuation (and COGS when sold).\n- Variances between estimated and actual charges are adjusted.\n\nImproves margin accuracy for imported goods.","D"],["Costing","How do you reconcile receipt accruals at month end?","- Run **accrual reconciliation** / review receipt accounting distributions for open accruals.\n- Investigate old accruals: missing invoices, wrong POs, quantity differences.\n- **Close** POs that are complete; **write off** with approval where justified.\n- Make sure Create Receipt Accounting and transfers ran before review.","D"],["Costing","How would you design costing for a vertically integrated pharma company (API, formulation, packaging, distribution)?","- **Process manufacturing** for API/formulation (recipes, yields, by-products); discrete or process for packaging.\n- **Cost orgs** per plant; **standard cost** with yearly cycle and roll-ups across levels.\n- **Lot-level valuation** where costs vary by lot (if required).\n- **Intercompany** (SFO) between manufacturing entities and distribution entities with transfer pricing.\n- **Variances** analysis (yield, usage, PPV); **inventory reserves** (expiry, quarantine).\n- **Landed costs** for imported materials.\n- GxP and finance controls on cost changes.","D"]]);
